# worker-run-request.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "admission": {
      "additionalProperties": false,
      "properties": {
        "mode": {
          "enum": [
            "enqueue_only",
            "run_now"
          ]
        },
        "reservation_id": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "mode"
      ],
      "type": "object"
    },
    "caller": {
      "additionalProperties": false,
      "properties": {
        "credential_ref": {
          "$ref": "#/$defs/ref"
        },
        "principal_ref": {
          "$ref": "#/$defs/ref"
        }
      },
      "required": [
        "principal_ref",
        "credential_ref"
      ],
      "type": "object"
    },
    "instructions": {
      "additionalProperties": false,
      "properties": {
        "body_ref": {
          "pattern": "^/chd/",
          "type": "string"
        },
        "criteria_ref": {
          "pattern": "^/chd/",
          "type": "string"
        },
        "request_digest": {
          "pattern": "^sha256:[A-Fa-f0-9]{64}$",
          "type": "string"
        }
      },
      "required": [
        "body_ref",
        "criteria_ref",
        "request_digest"
      ],
      "type": "object"
    },
    "provisioning": {
      "additionalProperties": false,
      "properties": {
        "mode": {
          "enum": [
            "fresh",
            "reuse",
            "fork"
          ]
        },
        "session_allocation_id": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "mode"
      ],
      "type": "object"
    },
    "ref": {
      "minLength": 1,
      "pattern": "^(?!.*\\s).+$",
      "type": "string"
    },
    "runtime": {
      "additionalProperties": false,
      "properties": {
        "context_window": {
          "minimum": 1,
          "type": "integer"
        },
        "max_turns": {
          "minimum": 1,
          "type": "integer"
        },
        "model": {
          "minLength": 1,
          "type": "string"
        },
        "provider": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "provider",
        "model",
        "context_window",
        "max_turns"
      ],
      "type": "object"
    },
    "target": {
      "additionalProperties": false,
      "properties": {
        "credential_scope": {
          "pattern": "^profile:[^/]+/credential:[^/]+$",
          "type": "string"
        },
        "gateway_id": {
          "$ref": "#/$defs/ref"
        },
        "gateway_url_ref": {
          "pattern": "^gateway:[^/]+$",
          "type": "string"
        }
      },
      "required": [
        "gateway_id",
        "gateway_url_ref",
        "credential_scope"
      ],
      "type": "object"
    },
    "work": {
      "additionalProperties": false,
      "properties": {
        "assignment_id": {
          "$ref": "#/$defs/ref"
        },
        "parent_bond_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "room": {
          "$ref": "#/$defs/ref"
        },
        "send_id": {
          "$ref": "#/$defs/ref"
        },
        "thread_root": {
          "minimum": 1,
          "type": [
            "integer",
            "null"
          ]
        },
        "ticket_id": {
          "$ref": "#/$defs/ref"
        }
      },
      "required": [
        "ticket_id",
        "assignment_id",
        "room",
        "send_id"
      ],
      "type": "object"
    },
    "worker": {
      "additionalProperties": false,
      "properties": {
        "agent_id": {
          "$ref": "#/$defs/ref"
        },
        "profile_ref": {
          "minLength": 1,
          "pattern": "^profile:[^/]+$",
          "type": "string"
        },
        "role": {
          "const": "worker"
        }
      },
      "required": [
        "agent_id",
        "profile_ref",
        "role"
      ],
      "type": "object"
    },
    "workspace": {
      "additionalProperties": false,
      "properties": {
        "scope": {
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "minItems": 1,
          "type": "array"
        },
        "workdir": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "workdir",
        "scope"
      ],
      "type": "object"
    }
  },
  "$id": "https://coding-hermes.local/chd32/schemas/worker-run-request.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "admission": {
      "$ref": "#/$defs/admission"
