      "type": "string"
    },
    "instructions": {
      "$ref": "#/$defs/instructions"
    },
    "provisioning": {
      "$ref": "#/$defs/provisioning"
    },
    "request_id": {
      "maxLength": 128,
      "minLength": 1,
      "type": "string"
    },
    "runtime": {
      "$ref": "#/$defs/runtime"
    },
    "schema_version": {
