    },
    "target": {
      "$ref": "#/$defs/target"
    },
    "work": {
      "$ref": "#/$defs/work"
    },
    "worker": {
      "$ref": "#/$defs/worker"
    },
    "workspace": {
      "$ref": "#/$defs/workspace"
    }
  },
  "required": [
    "schema_version",
    "request_id",
    "dedupe_key",
    "caller",
    "worker",
    "target",
    "work",
    "instructions",
    "workspace",
